param([string]$Directory,[string]$Native,[string]$CommonHarness,[string]$Harness,[string]$Case,[int]$OwnerPid,[string]$Nonce)
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Web.Extensions
function Source-Part([string]$Source,[string]$Start,[string]$End){$a=$Source.IndexOf($Start,[StringComparison]::Ordinal);$b=$Source.IndexOf($End,$a+$Start.Length,[StringComparison]::Ordinal);if($a -lt 0 -or $b -le $a){throw 'Exact production boundary missing'};return $Source.Substring($a,$b-$a)}
$broker=[IO.File]::ReadAllText((Join-Path $Native 'HyperVBroker.cs'));$common=[IO.File]::ReadAllText($CommonHarness)
foreach($line in @(' static string EmergencyEpoch(){return "runtime";}',' static bool Quiescing=false;static int QuiesceWriters=0;',' static bool TryShutdownHardwareStop(string id,string authority){throw new InvalidOperationException("Owner-exit fallback is outside this runtime emergency fixture");}')){if(-not $common.Contains($line)){throw 'Exact runtime-only fixture adapter missing'};$common=$common.Replace($line,'')}
$parts=@((Source-Part $broker '    private static Dictionary<string,object> Owned(' '    private static string Invoke('),(Source-Part $broker '    private static Dictionary<string,object> RecoverAllocation(' '    private static void CheckRemovalTree('),(Source-Part $broker '    private static byte[] ReadRequest(Stream pipe)' '    private static void Shutdown()'),(Source-Part $broker '    private static void Shutdown()' '    public static int Main('),(Source-Part $broker '    private static bool OwnerExited' '    private static DirectorySecurity PrivateAcl()'),(Source-Part $broker '    private static void RequestBounds(' '    private static bool OwnerExited'),(Source-Part $broker '    private static void ValidateKeys(' '    private static string Text('),(Source-Part $broker '    private static readonly CancellationTokenSource QuiesceCancellation' '    private static int ActiveRequests'))
$ever=@($broker -split '\r?\n'|Where-Object{$_.StartsWith('    private static bool EverReady(')});if($ever.Count -ne 1){throw 'Exact readiness method missing'}
$core='using System.IO.Pipes;using System.Runtime.InteropServices;using System.Security.Principal;using System.Security.AccessControl;'+[Environment]::NewLine+$common+[Environment]::NewLine+[IO.File]::ReadAllText($Harness)+[Environment]::NewLine+[IO.File]::ReadAllText((Join-Path $Native 'Resources.cs'))+[Environment]::NewLine+[IO.File]::ReadAllText((Join-Path $Native 'PowerProtection.cs'))+[Environment]::NewLine+'public static partial class MuHyperVBroker {'+[Environment]::NewLine+($parts -join [Environment]::NewLine)+$ever[0]+[Environment]::NewLine+'}'
Add-Type -TypeDefinition $core -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll')
if($Case -eq 'rpc'){[MuHyperVBroker]::RunShutdownRpc($Directory,$OwnerPid,$Nonce)}else{[Console]::Write([MuHyperVBroker]::RunShutdownFixture($Directory,$Case))}
